def p(t):doc.add_paragraph(t)
def h(t):doc.add_heading(t,1)
def new(t):doc.add_page_break();h(t)
def table(headers,rows,widths=None):
 t=doc.add_table(rows=1,cols=len(headers));t.autofit=False
 if widths:
  for c,w in zip(t.columns,widths):c.width=Inches(w)
 for i,head in enumerate(headers):t.rows[0].cells[i].text=str(head)
 for row in rows:
  for c,v in zip(t.add_row().cells,row):c.text=str(v)
 for ri,row in enumerate(t.rows):
  trpr=row._tr.get_or_add_trPr();cant=OxmlElement('w:cantSplit');trpr.append(cant)
  if ri==0:repeat=OxmlElement('w:tblHeader');trpr.append(repeat)
  for ci,c in enumerate(row.cells):
   if widths:c.width=Inches(widths[ci])
   tcpr=c._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
   for edge in ('top','left','bottom','right'):
    e=OxmlElement('w:'+edge);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
   tcpr.append(b);shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'DFEAF0' if ri==0 else ('F6F8FA' if ri%2==0 else 'FFFFFF'));tcpr.append(shade)
   for para in c.paragraphs:
    para.paragraph_format.space_before=Pt(4);para.paragraph_format.space_after=Pt(4)
    for run in para.runs:run.font.size=Pt(10);run.bold=ri==0
 doc.add_paragraph().paragraph_format.space_after=Pt(1)
def code(path):
 for line in path.read_text(encoding='utf-8').splitlines():
  for wrapped in textwrap.wrap(line,width=82,replace_whitespace=False,drop_whitespace=False) or ['']:
   q=doc.add_paragraph();q.paragraph_format.space_after=Pt(0);q.paragraph_format.line_spacing=1.0
   run=q.add_run(wrapped);run.font.name='Consolas';run.font.size=Pt(10)

